import pandas as pd


def clean(df):
    df = df.copy()
    # body_mass_g is stored as text with thousands separators (e.g. '3,075')
    df['body_mass_g'] = df['body_mass_g'].astype(str).str.replace(',', '', regex=False)
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    # remove the one exact duplicate row
    df = df.drop_duplicates()
    return df


def answer(df):
    result = {}
    grouped = df.groupby('species')['body_mass_g'].mean()
    for species, value in grouped.items():
        if pd.notna(value):
            result[species] = value
    return result
